INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(3525000, 3525, 0, 1, 0, 0, 0, 0, 'Bloodmyst Isle', 'The northern of the two Azuremyst Isles. The draenei first called it Silvergale, before the sickness spread and before they understood the full damage their crash had done. When the Exodar fell, smaller crystals rained down and buried themselves deep in the earth, and a blood-like fluid seeping from them and from the ship''s broken power core stained everything red.\n\nNow red crystals dot the land, the great pines have taken on a crimson tinge, the water runs red, and the wildlife has mutated into hostile creatures. Only the small southern part of the island, joined to Azuremyst by a bridge, is still untouched by the red mist.', 'warcraft.wiki.gg: Bloodmyst Isle (introduction, The Burning Crusade, Geography)'),
(3525001, 3525, 1, 1, 0, 0, 0, 0, 'Kessel''s Crossing', 'A draenei camp at the southern end of the island, by the bridge from Azuremyst, in the part of Bloodmyst the blood crystals have not yet reached. Its people hold the crossing against the naga of the nearby ruins and the beasts loosed by the crash.', 'warcraft.wiki.gg: Kessel''s Crossing; warcraft.wiki.gg: Lost Fold'),
(3525002, 3525, 1, 2, 0, 0, 0, 0, 'Blood Watch', 'The main draenei settlement on Bloodmyst, a forward outpost of the Hand of Argus built from repurposed escape pods and crystal fragments of the Exodar. Exarch Admetius leads it, and Harbinger Mikolaas keeps its defences.\n\nBlood Watch was founded to find a way to cleanse the island''s corruption and to fight the dangerous creatures loose on it. It has been under constant assault by blood elves ever since.', 'warcraft.wiki.gg: Blood Watch (History); warcraft.wiki.gg: Bloodmyst Isle (The Burning Crusade)'),
(3525003, 3525, 1, 3, 0, 0, 0, 0, 'Bladewood', 'The woods just north-west of Blood Watch, where the Sunhawk blood elves have set their camps. They harvest the irradiated crystals and alter them for some magical device of their own.', 'warcraft.wiki.gg: Bladewood'),
(3525004, 3525, 1, 4, 0, 0, 0, 0, 'The Cryo-Core', 'A cryogenic core of the Exodar that crashed on Bloodmyst, a holding area for sleeping passengers like the one in Ammen Vale. Some survived the crash inside it, only to be found and killed by the blood elves who came to scavenge it.\n\nIt was here that Vindicator Saruan, one of the leaders of the Hand of Argus, was taken after the crash, and tortured to death by Matis the Cruel.', 'warcraft.wiki.gg: Cryo-Core'),
(3525005, 3525, 1, 5, 0, 0, 0, 0, 'The Vector Coil', 'A power core of the Exodar that crashed into western Bloodmyst, and the headquarters of the Sunhawk blood elves under their eredar mistress Sironas. They used it to open a Sun Gate, a dimensional rift that brings blood elf reinforcements from Outland.\n\nThe core leaks volatile fluids that have turned the island''s water red and irradiated everything around it, and the Sunhawks use the fallout to poison the land deliberately. The creatures closest to it have changed the most.', 'warcraft.wiki.gg: Vector Coil (History)'),
(3525006, 3525, 1, 6, 0, 0, 0, 0, 'The Warp Piston', 'A fallen piece of the Exodar in northern Bloodmyst, where the Sunhawks first built their Sun Gate before moving it south of the Vector Coil. Voidwalker anomalies have infested what was left behind.', 'warcraft.wiki.gg: Warp Piston'),
(3525007, 3525, 1, 7, 0, 0, 0, 0, 'Vindicator''s Rest', 'A small draenei outpost in a graveyard in north-western Bloodmyst. A Hand of Argus squad searching for the Sun Gate was outnumbered by blood elves and mutated beasts, and dug in here as a forward base.', 'warcraft.wiki.gg: Vindicator''s Rest'),
(3525008, 3525, 1, 8, 0, 0, 0, 0, 'Nazzivian', 'A satyr camp in south-western Bloodmyst, base of the Nazzivus sect. Its monument is carved with glyphs telling how the Highborne night elves willingly became satyrs and servants of the Burning Legion, and the Legion means to turn the sect against the draenei.', 'warcraft.wiki.gg: Nazzivian'),
(3525009, 3525, 1, 9, 0, 0, 0, 0, 'Axxarien', 'A satyr outpost in northern Bloodmyst, home of the Axxarien sect. They have taken the crystal shards of the Exodar''s crash and use them as weapons.', 'warcraft.wiki.gg: Axxarien'),
(3525010, 3525, 1, 10, 0, 0, 0, 0, 'Ruins of Loreth''Aran', 'The remains of a great night elven city in north-eastern Bloodmyst, older than the War of the Ancients. Loreth''Aran was blessed by Ysera, Aspect of the green dragonflight, and its Dragon Riders, led by Prince Toreth, rode green dragons into battle and lived beside them for centuries.\n\nWrathscale naga now hold the ruins. More of the city lies scattered on Wyrmscar Island to the north-east.', 'warcraft.wiki.gg: Ruins of Loreth''Aran (History)'),
(3525011, 3525, 1, 11, 0, 0, 0, 0, 'Wrathscale Lair', 'Ancient night elven ruins on a hilltop in Bloodmyst, now held by the Wrathscale naga. From here they raid the draenei camp at Kessel''s Crossing by night.', 'warcraft.wiki.gg: Wrathscale Lair'),
(3525012, 3525, 1, 12, 0, 0, 0, 0, 'Amberweb Pass', 'A mountain pass north of the Vector Coil, poisoned by the fluid seeping from the crystals. Its spiders have mutated and multiplied into massive, extremely aggressive creatures under their matriarch, Zarakh, and the Blood Watch survey team sent to explore it was ambushed and lost.', 'warcraft.wiki.gg: Amberweb Pass'),
(3525013, 3525, 1, 13, 0, 0, 0, 0, 'Blacksilt Shore and the Bloodwash', 'The black-sand beaches of south-western and northern Bloodmyst, crowded with the huts of the Blacksilt murlocs. One of them, Cruelfin, made himself a pendant from an irradiated crystal and quickly outgrew his kin.\n\nAn Explorers'' League scholar has taken to hiding in an old turtle shell on the Bloodwash to observe the murlocs, collecting their idols for the museum in Ironforge.', 'warcraft.wiki.gg: Blacksilt Shore; warcraft.wiki.gg: Bloodwash'),
(3525014, 3525, 1, 14, 0, 0, 0, 0, 'Bristlelimb Enclave', 'A large Bristlelimb furbolg village south of Wrathscale Lair. The Bristlelimb slaughter any Stillpine who stray near, and have taken the Stillpine chieftain''s daughter captive, meaning to sacrifice her to their gods.', 'warcraft.wiki.gg: Bristlelimb Enclave'),
(3525015, 3525, 1, 15, 0, 0, 0, 0, 'Wyrmscar Island', 'An island north-east of Bloodmyst, once part of Loreth''Aran. After the Dragon Wars and the Sundering it became a graveyard: the bones of dragons, the restless spirits of green whelplings slain by the black dragonflight, and the ghost of Prince Toreth, the last to die.\n\nOn its central hill, Talon Stand, the hatred of Razormaw, the black dragon who led the slaughter, is so strong that his shade still haunts the island. Ghostly whelps flit about Veridian Point at its northern tip.', 'warcraft.wiki.gg: Wyrmscar Island (History); warcraft.wiki.gg: Talon Stand; warcraft.wiki.gg: Veridian Point'),
(3525016, 3525, 1, 16, 0, 0, 0, 0, 'Ragefeather Ridge', 'Hills in north-eastern Bloodmyst full of the camps of the Ragefeather owlkin, corrupted by the Exodar''s crystals. For reasons of their own, they crossed to Wyrmscar Island and carried off the ancient dragon bones there.', 'warcraft.wiki.gg: Ragefeather Ridge'),
(3525017, 3525, 1, 17, 0, 0, 0, 0, 'The Bloodcursed Reef', 'A naga-infested reef east of Wyrmscar Island, where the wrecks of many ships lie broken on the sea floor, crewed now by the ghosts of the humans who sailed them. Sailors say the bloodcurse sank them all.\n\nDuring the Great Sundering, thousands of night elves faded into oblivion here, and in their place rose the Bloodcursed naga. On nearby Bloodcurse Isle, a statue of Queen Azshara stands at the highest point.', 'warcraft.wiki.gg: Bloodcursed Reef; warcraft.wiki.gg: Bloodcurse Isle'),
(3525018, 3525, 1, 18, 0, 0, 0, 0, 'The Foul Pool and the Hidden Reef', 'The Foul Pool is a small lake in north-western Bloodmyst. When the Exodar''s power core lodged in the mountain to the west, its leaking fluids flooded the island''s water, and the water elementals here are slowly turning to crystal. A mad blood elf researcher, Tel''athion the Impure, makes things worse from his camp nearby.\n\nOff the north-western coast, an underwater temple called the Hidden Reef holds the wrecks of two human ships and the lord of the region''s water elementals, Aqueous.', 'warcraft.wiki.gg: Foul Pool; warcraft.wiki.gg: Hidden Reef; warcraft.wiki.gg: Tel''athion''s Camp'),
(3525030, 3525, 2, 1, 0, 0, 0, 0, 'Exarch Admetius', 'The leader of Blood Watch for the Hand of Argus, charged with cleansing the island and holding it against the Sunhawks and the creatures loosed by the crash.', 'warcraft.wiki.gg: Blood Watch (History)'),
(3525031, 3525, 2, 2, 0, 0, 0, 0, 'Harbinger Mikolaas', 'Charged by the draenei leaders in the Exodar with the defence of Blood Watch and a variety of other duties. He studies the island''s crystals, both those the crash left and those the blood elves have altered, to understand what they are doing to the land.', 'warcraft.wiki.gg: Blood Watch (History); warcraft.wiki.gg: Bladewood; warcraft.wiki.gg: Lost Fold'),
(3525032, 3525, 2, 3, 0, 0, 0, 0, 'Prince Toreth', 'The prince of Loreth''Aran and leader of its Dragon Riders, the last to die when the black dragons destroyed the city. With his last breath he swore a blood oath with the land itself and became the sole keeper of his people''s history.\n\nHis soul cannot rest until he is sure the story of the Dragon Riders of Loreth''Aran will not be lost to time, and he haunts Wyrmscar Island among the bones of the dragons his people loved.', 'warcraft.wiki.gg: Wyrmscar Island (History); warcraft.wiki.gg: Ruins of Loreth''Aran'),
(3525033, 3525, 2, 4, 0, 0, 0, 0, 'Captain Edward Hanes', 'Captain of the ship Lost Hope, which the bloodcurse sank on the Bloodcursed Reef in the years after the Second War. His spirit is trapped on the island beside the reef, and he warns any who will listen of the curse that took his ship.', 'warcraft.wiki.gg: Bloodmyst Isle (Early history); warcraft.wiki.gg: Odesyus'' Landing; warcraft.wiki.gg: Bloodcursed Reef'),
(3525034, 3525, 2, 5, 0, 0, 0, 0, 'Morae and Galaen', 'Galaen was a technician who worked in the Exodar''s Cryo-Core. He survived the crash, only to be killed by blood elf infiltrators who came to scavenge the core; his last thoughts were of his wife, Morae, who searched the island for him.', 'warcraft.wiki.gg: Cryo-Core'),
(3525035, 3525, 2, 6, 0, 0, 0, 0, 'Matis the Cruel', 'A draenei who serves the Sunhawks, and the one who tortured and killed Vindicator Saruan in the Cryo-Core. That one of their own could do such a thing is a hard thing for the draenei to accept.', 'warcraft.wiki.gg: Cryo-Core; warcraft.wiki.gg: Sironas'),
(3525036, 3525, 2, 7, 0, 0, 0, 0, 'Sironas', 'A man''ari, one of the eredar who accepted the Legion''s power, in the service of Prince Kael''thas. She slipped aboard the Exodar during the battle between the blood elves and the draenei, and was responsible for its crash.\n\nAfterwards she gathered the surviving blood elves and led them to Bloodmyst as the Sunhawks. She means to capture the Exodar, enslave its naaru, O''ros, and corrupt the draenei into demons like herself.', 'warcraft.wiki.gg: Sironas (introduction, The Burning Crusade)'),
(3525050, 3525, 3, 1, 0, 0, 0, 0, 'From Silvergale to Bloodmyst', 'The draenei named the island Silvergale when they arrived. Then the blood-like fluid began seeping out of the buried crystals and the Vector Coil, staining earth, trees and water red and mutating the animals. Even the gentle flutterers grew so corrupted they damaged everything they touched.\n\nThe crash released Outland''s creatures too, ravagers among them, and the draenei have had to cull them to protect the island''s balance. Hand of Argus outposts were raised to find a cure.', 'warcraft.wiki.gg: Bloodmyst Isle (introduction, The Burning Crusade)'),
(3525051, 3525, 3, 2, 0, 0, 0, 0, 'The Sunhawks and the Sun Gate', 'The blood elves who sabotaged the Exodar survived the crash too. Gathered by Sironas, they call themselves the Sunhawks and serve Kael''thas Sunstrider. Their goal is to retake the ship, which their prince counts as stolen from him.\n\nWith the remains of the Vector Coil they built the Sun Gate, a rift through which reinforcements come from Outland. They poison the island on purpose with the core''s fallout, and scavenge every piece of wreckage they can reach.', 'warcraft.wiki.gg: Sironas; warcraft.wiki.gg: Vector Coil; warcraft.wiki.gg: Bloodmyst Isle (The Burning Crusade)'),
(3525052, 3525, 3, 3, 0, 0, 0, 0, 'The Dragon Riders of Loreth''Aran', 'Long before the Sundering, the island was a mountainous forest on Kalimdor''s western edge, left wild by the Kaldorei Empire as a hunting ground. Its great city, Loreth''Aran, was home to the Dragon Riders, blessed by Ysera to fly beside her green dragons.\n\nIn the Dragon Wars the black dragonflight betrayed their green kin. Razormaw, a lieutenant of Deathwing, led them down on the unwary riders and wiped out Loreth''Aran in a storm of fire. The Sundering finished the work: the sea rushed in, the earth heaved, and only scattered ruins on separate islands remain.', 'warcraft.wiki.gg: Bloodmyst Isle (Early history); warcraft.wiki.gg: Ruins of Loreth''Aran (History)');
